159	      {includeQuantity && (
160	        <Text lineHeight={1} color="gray.700" fontSize="sm">
161	          <FormattedMessage
162	            defaultMessage="Quantity: {quantity}"
163	            values={{ quantity: variant.quantity }}
164	            id="item_attributes.label.quantity"
165	          />
166	        </Text>
167	      )}
168	
169	      {!productBundleIsLoading && productBundleData && !productBundleVariantData && (
170	        <Box>
171	          {/* Deviation from the base file (same labelled-comment convention as
172	                        product-view/index.tsx:659-661/1019-1022): added `?.` before `.map` —
173	                        `bundledProducts` is itself optional on the SDK's real Product type even
174	                        once `productBundleData` is truthy, which strict null checks catches and
175	                        the base file's plain JS did not need to guard against. This is a real,
176	                        narrow behaviour difference from base, not a pure typing satisfier: base
177	                        would throw here if `bundledProducts` were ever undefined on an otherwise
178	                        truthy `productBundleData`; this renders nothing instead. Directionally
