6	 */
7	
8	/*
9	 * Copy-first port of node_modules/@salesforce/retail-react-app/app/components/item-variant/item-price.jsx
10	 * (retail-react-app 10.0.0), converted to TypeScript per AGENTS.md's copy-first rule (SFCC-270,
11	 * plan step 2.1). Zero functional diff beyond the TypeScript annotations below and a temporary
12	 * `[overrides]` console.log marker (verified live, then removed). The
13	 * `<Stack textAlign={align} ... {...props}>`
14	 * defaults-then-spread prop order is preserved exactly, unchanged from base.
15	 *
16	 * `useItemVariant` is already imported via the relative `'.'` in the base file — unchanged here.
17	 * `display-price` and the `useCurrency`/`app/hooks` barrel are not overridden anywhere in this
18	 * repo (verified by directory listing at time of writing), so both stay on the base
19	 * `@salesforce/retail-react-app/...` path.
20	 *
21	 * SFCC-270 (plan step 2.2): restyled to the Figma cart-item spec (`textStyle="price"`) via
22	 * item-variant.css.ts's `price` part. The actual price digits render via the base,
23	 * un-overridden `display-price`/`current-price` components below (out of this commit's file
24	 * scope) — confirmed by reading both that neither sets its own competing font-size, so the
25	 * textStyle cascades down via ordinary CSS inheritance rather than needing either file touched.
26	 * `PricePerItem`'s own `fontSize={{base: '12px', lg: '14px'}}` is untouched — no Figma value
27	 * was given for it at this step.
28	 */
29	import React from 'react';
30	import { FormattedMessage, FormattedNumber } from 'react-intl';
31	import {
32	  Stack,
33	  Text,
34	  useBreakpointValue,
35	  useMultiStyleConfig,
36	} from '@salesforce/retail-react-app/app/components/shared/ui';
37	import { useItemVariant } from '.';
38	import { getPriceData } from '@salesforce/retail-react-app/app/utils/product-utils';
39	import DisplayPrice from '@salesforce/retail-react-app/app/components/display-price';
40	
41	const ZIMM_CART_ITEM_VARIANT_RECIPE = 'ZimmCartItemVariant';
42	
43	// See index.tsx's own note on why this is `any` rather than a structural type.
44	type SfccVariant = any;
45	
46	type PricePerItemProps = {
47	  currency: string;
48	  // Deviation from the base file (same labelled-comment convention as
49	  // product-view/index.tsx:659-661/1019-1022): base PropTypes declares this as optional
50	  // (`PropTypes.number`, no `.isRequired`), but both real call sites below it — the only two
51	  // in this file — only ever render <PricePerItem> from behind a `priceData?.pricePerUnit &&`
52	  // guard, so `basePrice` is never actually undefined when this renders. Typed as required to
53	  // satisfy `<FormattedNumber value={basePrice} />`'s `number | bigint` prop under strict null
54	  // checks, without inventing a fallback value the base file never had.
55	  basePrice: number;
56	};
57	
58	const PricePerItem = ({ currency, basePrice }: PricePerItemProps) => {
59	  return (
60	    <Text fontSize={{ base: '12px', lg: '14px' }}>
61	      <FormattedNumber style="currency" currency={currency} value={basePrice} />
62	      <FormattedMessage
63	        defaultMessage="ea"
64	        id="price_per_item.label.each"
65	        description="Abbreviated 'each', follows price per item, like $10/ea"
66	      />
67	    </Text>
68	  );
69	};
70	
71	type ItemPriceProps = {
72	  currency: string;
73	  align?: string;
74	  baseDirection?: string;
75	} & Record<string, any>;
76	
77	/**
78	 * In the context of a cart product item variant, this component renders the item's
79	 * pricing, taking into account applied discounts as well as base item prices.
80	 */
81	const ItemPrice = ({ currency, align = 'right', baseDirection = 'column', ...props }: ItemPriceProps) => {
82	  const variant: SfccVariant = useItemVariant();
83	  const styles = useMultiStyleConfig(ZIMM_CART_ITEM_VARIANT_RECIPE, {});
84	  const { price, priceAfterItemDiscount } = variant;
85	  const isASet = variant?.type?.set;
86	  const isMaster = variant?.type?.master;
87	  let priceData;
88	  // When variant has basket pricing, we should prioritize these prices for displaying
89	  // since they may have take promotion/discount into account
90	  // NOTE: try NOT to re-calculate these values since basket-level discount is complicated
91	  if (variant?.itemId) {
92	    priceData = {
93	      currentPrice: priceAfterItemDiscount,
94	      // we don't want to show strikethrough price for cart since listPrice is not available via basket pricing
95	      listPrice: null,
96	      pricePerUnit: variant?.pricePerUnit,
97	      isASet,
98	      isMaster,
99	      isRange: isASet || isMaster || false,
100	      isOnSale: price > priceAfterItemDiscount,
101	    };
102	  } else {
103	    // for wishlist page we extract price info from variant/product obj
104	    priceData = getPriceData(variant);
105	  }
106	  const isDesktop = useBreakpointValue({ base: false, lg: true });
107	
108	  return (
109	    <Stack
110	      sx={styles.price}
111	      textAlign={align}
112	      direction={baseDirection}
113	      justifyContent={align === 'left' ? 'flex-start' : 'flex-end'}
114	      alignItems="baseline"
115	      spacing={priceData?.isOnSale ? 0 : 1}
116	      wrap="nowrap"
117	      {...props}
118	    >
119	      {!isDesktop && variant?.quantity > 1 && !isASet && priceData?.pricePerUnit && (
120	        <PricePerItem currency={currency} basePrice={priceData.pricePerUnit} />
121	      )}
122	
123	      {variant?.itemId ? (
124	        <DisplayPrice
125	          labelForA11y={variant?.name}
126	          currency={currency}
127	          priceData={priceData}
128	          listPriceProps={{ fontSize: 'sm' }}
129	        />
130	      ) : (
131	        <DisplayPrice
132	          labelForA11y={variant?.name}
133	          currency={currency}
134	          priceData={priceData}
135	          quantity={variant?.quantity}
136	          listPriceProps={{ fontSize: 'sm' }}
137	        />
138	      )}
139	
140	      {isDesktop && variant?.quantity > 1 && !isASet && priceData?.pricePerUnit && (
141	        <PricePerItem currency={currency} basePrice={priceData.pricePerUnit} />
142	      )}
143	    </Stack>
144	  );
145	};
146	
147	export default ItemPrice;
148

